#!/usr/bin/env python3
"""Naive, literal reference implementation of the contract (for testing only)."""
import sys, json, re
from fractions import Fraction

ROOT = {"version","config","model","connections","packets"}
CFGK = {"slots","window","idle_timeout","len_quantum","gap_quantum","rate_num",
        "rate_den","bucket_capacity","initial_tokens","pending_capacity","lanes",
        "service","fallback","time_edges","count_edges","probability"}
MODK = {"classes","embedding_dim","length_embedding","gap_embedding","kernel",
        "conv_weights","conv_bias","conv_shift","dense_weights","dense_bias"}
CONK = {"id","slot","label","split"}
PCK = {"time","connection","length","draw"}
IDPAT = re.compile(r"^[A-Za-z0-9_-]{1,32}$")

class Bad(Exception): pass

def isint(x):
    return isinstance(x, int) and not isinstance(x, bool)

def rng(x, lo, hi):
    if not isint(x) or x < lo or x > hi: raise Bad()
    return x

def obj(x, keys):
    if not isinstance(x, dict) or set(x.keys()) != keys: raise Bad()
    return x

def lst(x):
    if not isinstance(x, list): raise Bad()
    return x

def check(doc):
    obj(doc, ROOT)
    if not isint(doc["version"]) or doc["version"] != 1: raise Bad()
    cfg = obj(doc["config"], CFGK)
    mdl = obj(doc["model"], MODK)
    C = rng(mdl["classes"], 2, 8)
    E = rng(mdl["embedding_dim"], 1, 4)
    for key in ("length_embedding","gap_embedding"):
        t = lst(mdl[key])
        if len(t) != 16: raise Bad()
        for row in t:
            lst(row)
            if len(row) != E: raise Bad()
            for v in row: rng(v, -128, 127)
    K = rng(mdl["kernel"], 1, 5)
    cw = lst(mdl["conv_weights"])
    F = len(cw)
    if not (1 <= F <= 8): raise Bad()
    for filt in cw:
        lst(filt)
        if len(filt) != K: raise Bad()
        for row in filt:
            lst(row)
            if len(row) != 2*E: raise Bad()
            for v in row: rng(v, -128, 127)
    cb = lst(mdl["conv_bias"])
    if len(cb) != F: raise Bad()
    for v in cb: rng(v, -2147483648, 2147483647)
    cs = lst(mdl["conv_shift"])
    if len(cs) != F: raise Bad()
    for v in cs: rng(v, 0, 16)
    dw = lst(mdl["dense_weights"])
    if len(dw) != C: raise Bad()
    for row in dw:
        lst(row)
        if len(row) != F: raise Bad()
        for v in row: rng(v, -128, 127)
    db = lst(mdl["dense_bias"])
    if len(db) != C: raise Bad()
    for v in db: rng(v, -2147483648, 2147483647)

    S = rng(cfg["slots"], 1, 256)
    W = rng(cfg["window"], 1, 16)
    if K > W: raise Bad()
    rng(cfg["idle_timeout"], 1, 10**12)
    rng(cfg["len_quantum"], 1, 65535)
    rng(cfg["gap_quantum"], 1, 65535)
    rng(cfg["rate_num"], 1, 10**6)
    rng(cfg["rate_den"], 1, 10**6)
    bc = rng(cfg["bucket_capacity"], 1, 512)
    rng(cfg["initial_tokens"], 0, bc)
    rng(cfg["pending_capacity"], 1, 512)
    rng(cfg["lanes"], 1, 4)
    svc = lst(cfg["service"])
    if len(svc) != C: raise Bad()
    for v in svc: rng(v, 1, 10**6)
    rng(cfg["fallback"], 0, C-1)
    for key, hi in (("time_edges",10**12), ("count_edges",20000)):
        e = lst(cfg[key])
        if not (1 <= len(e) <= 16): raise Bad()
        for v in e: rng(v, 0, hi)
        if e[0] != 0: raise Bad()
        for i in range(1, len(e)):
            if e[i] <= e[i-1]: raise Bad()
    prob = lst(cfg["probability"])
    if len(prob) != len(cfg["time_edges"]): raise Bad()
    for row in prob:
        lst(row)
        if len(row) != len(cfg["count_edges"]): raise Bad()
        for v in row: rng(v, 0, 65536)

    conns = lst(doc["connections"])
    if len(conns) > 2048: raise Bad()
    seen = set()
    for c in conns:
        obj(c, CONK)
        if not isinstance(c["id"], str) or not IDPAT.match(c["id"]): raise Bad()
        if c["id"] in seen: raise Bad()
        seen.add(c["id"])
        rng(c["slot"], 0, S-1)
        rng(c["label"], 0, C-1)
        if c["split"] not in ("dev","eval"): raise Bad()
    pk = lst(doc["packets"])
    if len(pk) > 20000: raise Bad()
    prev = None
    for p in pk:
        obj(p, PCK)
        t = rng(p["time"], 0, 10**12)
        if prev is not None and t < prev: raise Bad()
        prev = t
        if not isinstance(p["connection"], str) or p["connection"] not in seen: raise Bad()
        rng(p["length"], 0, 65535)
        rng(p["draw"], 0, 65535)
    return cfg, mdl, doc["connections"], doc["packets"]

def cnn(window, mdl):
    E = mdl["embedding_dim"]; K = mdl["kernel"]
    le = mdl["length_embedding"]; ge = mdl["gap_embedding"]
    cw = mdl["conv_weights"]; cb = mdl["conv_bias"]; cs = mdl["conv_shift"]
    dw = mdl["dense_weights"]; db = mdl["dense_bias"]
    W = len(window)
    F = len(cw); C = len(dw)
    x = []
    for (a,b) in window:
        x.append(list(le[a]) + list(ge[b]))
    pooled = []
    for f in range(F):
        vals = []
        for j in range(W-K+1):
            z = cb[f]
            for k in range(K):
                for d in range(2*E):
                    z += cw[f][k][d] * x[j+k][d]
            sh = cs[f]
            if sh:
                dd = 2**sh
                neg = z < 0
                az = -z if neg else z
                q = az // dd
                r = az - q*dd
                if 2*r >= dd: q += 1
                z = -q if neg else q
            if z < 0: z = 0
            if z > 127: z = 127
            vals.append(z)
        pooled.append(max(vals))
    logits = []
    for c in range(C):
        v = db[c]
        for f in range(F):
            v += dw[c][f]*pooled[f]
        logits.append(v)
    best = 0
    for c in range(1, C):
        if logits[c] > logits[best]: best = c
    return logits, best

def edge(edges, v):
    idx = 0
    for i, e in enumerate(edges):
        if e <= v: idx = i
        else: break
    return idx

def replay(cfg, mdl, conns, pkts):
    C = mdl["classes"]; S = cfg["slots"]; W = cfg["window"]; L = cfg["lanes"]
    idle = cfg["idle_timeout"]; lq = cfg["len_quantum"]; gq = cfg["gap_quantum"]
    rn = cfg["rate_num"]; rd = cfg["rate_den"]; bc = cfg["bucket_capacity"]
    pc = cfg["pending_capacity"]; svc = cfg["service"]; fb = cfg["fallback"]
    te = cfg["time_edges"]; ce = cfg["count_edges"]; prob = cfg["probability"]

    slots = []
    for i in range(S):
        slots.append({"occ": None, "gen": 0, "win": [], "cls": None,
                      "lastapp": -1, "anchor": 0, "backlog": 0, "lastt": None})
    lanes = [0]*L
    pending = []
    alljobs = []
    credit = cfg["initial_tokens"] * rd
    last_refill = 0
    nextid = 0
    cindex = {c["id"]: i for i, c in enumerate(conns)}
    votes = [[0]*C for _ in conns]
    pcount = [0]*len(conns)
    pkt_out = []

    def finish(due_t):
        todo = [j for j in pending if j["done"] <= due_t]
        todo.sort(key=lambda j: (j["done"], j["id"]))
        for j in todo:
            pending.remove(j)
            sl = slots[j["slot"]]
            if sl["occ"] is None or sl["occ"] != j["conn"] or sl["gen"] != j["gen"]:
                j["status"] = "stale"
            elif j["id"] <= sl["lastapp"]:
                j["status"] = "superseded"
            else:
                j["status"] = "applied"
                sl["cls"] = j["prediction"]
                sl["lastapp"] = j["id"]

    for idx, p in enumerate(pkts):
        t = p["time"]
        finish(t)
        credit = min(bc*rd, credit + (t - last_refill)*rn)
        last_refill = t
        ci = cindex[p["connection"]]
        s = conns[ci]["slot"]
        sl = slots[s]
        reset = False
        if sl["occ"] is None or sl["occ"] != ci:
            reset = True
        elif t - sl["lastt"] >= idle:
            reset = True
        if reset:
            sl["gen"] += 1
            sl["occ"] = ci
            sl["win"] = []
            sl["cls"] = None
            sl["lastapp"] = -1
            sl["anchor"] = t
            sl["backlog"] = 0
            gap = 0
        else:
            gap = t - sl["lastt"]
        sl["lastt"] = t
        qa = min(15, p["length"] // lq)
        qb = min(15, gap // gq)
        sl["win"].append([qa, qb])
        if len(sl["win"]) > W:
            sl["win"] = sl["win"][-W:]
        sl["backlog"] += 1
        fwd = sl["cls"] if sl["cls"] is not None else fb
        votes[ci][fwd] += 1
        pcount[ci] += 1
        job_id = None
        if len(sl["win"]) < W:
            dec = "warmup"
        else:
            Ti = t - sl["anchor"]; Ci = sl["backlog"]
            pv = prob[edge(te, Ti)][edge(ce, Ci)]
            if p["draw"] >= pv:
                dec = "probability"
            elif credit < rd:
                dec = "tokens"
            elif len(pending) >= pc:
                dec = "queue"
            else:
                dec = "sent"
                credit -= rd
                win = [row[:] for row in sl["win"]]
                logits, pred = cnn(win, mdl)
                jid = nextid; nextid += 1
                lane = 0
                for li in range(1, L):
                    if lanes[li] < lanes[lane]: lane = li
                start = max(t, lanes[lane])
                done = start + svc[pred]
                lanes[lane] = done
                rec = {"id": jid, "packet": idx, "connection": conns[ci]["id"],
                       "slot": s, "generation": sl["gen"], "lane": lane,
                       "start": start, "done": done, "window": win,
                       "logits": logits, "prediction": pred, "status": None}
                pending.append(rec)
                alljobs.append(rec)
                sl["anchor"] = t
                sl["backlog"] = 0
                job_id = jid
        pkt_out.append({"index": idx, "connection": p["connection"],
                        "generation": sl["gen"], "forward": fwd, "decision": dec,
                        "credit": credit, "job": job_id})
    finish(2*10**12 + 10**7)

    conn_out = []
    preds = []
    for ci in range(len(conns)):
        c = conns[ci]
        v = votes[ci]
        pr = None
        if pcount[ci] > 0:
            pr = 0
            for k in range(1, C):
                if v[k] > v[pr]: pr = k
        preds.append(pr)
        conn_out.append({"id": c["id"], "split": c["split"], "label": c["label"],
                         "packets": pcount[ci], "votes": v, "prediction": pr})

    reports = {}
    for split in ("dev","eval"):
        conf = [[0]*C for _ in range(C)]
        n = 0
        for ci in range(len(conns)):
            if conns[ci]["split"] == split and pcount[ci] > 0:
                n += 1
                conf[conns[ci]["label"]][preds[ci]] += 1
        tot = Fraction(0)
        for c in range(C):
            tp = conf[c][c]
            fp = sum(conf[r][c] for r in range(C)) - tp
            fn = sum(conf[c]) - tp
            den = 2*tp + fp + fn
            if den == 0: continue
            tot += Fraction(2*tp, den)
        m = tot / C
        reports[split] = {"connections": n, "confusion": conf,
                          "macro_f1": [m.numerator, m.denominator]}

    return {"packets": pkt_out, "jobs": alljobs, "connections": conn_out,
            "reports": reports}

def main():
    raw = sys.stdin.buffer.read()
    try:
        if len(raw) > 16*1024*1024: raise Bad()
        doc = json.loads(raw.decode("utf-8"))
        cfg, mdl, conns, pkts = check(doc)
        out = replay(cfg, mdl, conns, pkts)
        sys.stdout.write(json.dumps(out))
        sys.stdout.write("\n")
    except Exception:
        sys.stdout.write(json.dumps({"error":"invalid-input"}) + "\n")

if __name__ == "__main__":
    main()
